#!/usr/bin/env node
/**
 * Audit native names mentioned in SA-MP/open.mp skill docs against the matrix
 * generated by native-parity.js.
 *
 *   node bin/samp-claim-audit.js                 # every SA-MP skill
 *   node bin/samp-claim-audit.js --json
 *
 * Flags only claims the matrix can settle:
 *   - a `Name(` that exists in neither stdlib  -> suspected invented native
 *   - a legacy-only native presented as current -> removed/shim, needs a note
 * It does not judge prose, only symbol existence.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const MATRIX = path.join(__dirname, 'data/native-ownership.json');
const SKILLS = path.join(ROOT, '.agents/skills');
const SKILL_PREFIXES = ['samp-', 'openmp-'];

function parseArgs(argv) {
  const args = { json: false };
  for (const arg of argv) {
    if (arg === '--json') args.json = true;
    else if (arg.startsWith('--')) {
      console.error(`samp-claim-audit: unknown argument '${arg}'`);
      process.exit(2);
    }
  }
  return args;
}

function loadMatrix() {
  if (!fs.existsSync(MATRIX)) {
    console.error(`samp-claim-audit: matrix missing at ${MATRIX} — run bin/native-parity.js`);
    process.exit(2);
  }
  const data = JSON.parse(fs.readFileSync(MATRIX, 'utf8'));
  return {
    modernOnly: new Set(data.modernOnly.map((entry) => entry.name)),
    legacyOnly: new Map(data.legacyOnly.map((entry) => [entry.name, entry])),
    shared: new Set(data.shared || []),
    unverified: new Map((data.unverified || []).map((entry) => [entry.name, entry])),
  };
}

function skillDirs() {
  return fs
    .readdirSync(SKILLS, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && SKILL_PREFIXES.some((prefix) => entry.name.startsWith(prefix)))
    .map((entry) => entry.name)
    .sort();
}

function symbolsIn(markdown) {
  /* `Name(` and `Name()` are calls; bare `Name` is skipped to avoid prose nouns. */
  const found = new Map();
  const re = /`([A-Za-z_]\w*)\s*\(/g;
  let match;
  while ((match = re.exec(markdown)) !== null) {
    const name = match[1];
    if (name.length < 3) continue;
    if (!found.has(name)) {
      const line = markdown.slice(0, match.index).split('\n').length;
      found.set(name, line);
    }
  }
  return found;
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const matrix = loadMatrix();
  const report = [];

  for (const skill of skillDirs()) {
    const file = path.join(SKILLS, skill, 'SKILL.md');
    if (!fs.existsSync(file)) continue;
    const markdown = fs.readFileSync(file, 'utf8');

    for (const [name, line] of symbolsIn(markdown)) {
      const legacy = matrix.legacyOnly.get(name);
      if (legacy) {
        report.push({
          skill,
          line,
          name,
          severity: legacy.shim ? 'warning' : 'error',
          kind: legacy.shim ? 'removed-native-shim' : 'legacy-only-native',
          message: legacy.shim
            ? `${name}() bukan native open.mp lagi (hanya stock shim deprecated)`
            : `${name}() hanya ada di 0.3.7 — bukan bagian dari API open.mp`,
        });
        continue;
      }

      if (matrix.modernOnly.has(name) || matrix.shared.has(name) || matrix.unverified.has(name)) continue;

      /* Unknown to both stdlibs: only flag it when the doc presents it as a native. */
      const contextRe = new RegExp('`[^`\\n]*\\b' + name + '\\s*\\([^`\\n]*`[^\\n]*(?:native|Native|NATIVE)');
      if (contextRe.test(markdown)) {
        report.push({
          skill,
          line,
          name,
          severity: 'warning',
          kind: 'unverified-native',
          message: `${name}() tidak ada di stdlib inti — pastikan berasal dari plugin/include yang dipasang, bukan nama karangan`,
        });
      }
    }
  }

  /* Claims that a symbol is open.mp-only while it exists in 0.3.7 too. */
  const claimRe = /(open\.mp[- ]only|hanya (?:di )?open\.mp|baru di open\.mp|newly? (?:in|native)|ditambahkan (?:di|ke) open\.mp)/i;
  for (const skill of skillDirs()) {
    const file = path.join(SKILLS, skill, 'SKILL.md');
    if (!fs.existsSync(file)) continue;
    const lines = fs.readFileSync(file, 'utf8').split('\n');

    lines.forEach((line, index) => {
      if (!claimRe.test(line)) return;
      const nameRe = /`([A-Za-z_]\w*)\s*\(?/g;
      let match;
      while ((match = nameRe.exec(line)) !== null) {
        const name = match[1];
        if (name.length < 4) continue;
        if (!matrix.shared.has(name) && !matrix.legacyOnly.has(name) && !matrix.unverified.has(name)) continue;
        report.push({
          skill,
          line: index + 1,
          name,
          severity: 'error',
          kind: 'false-modern-claim',
          message: `${name}() diklaim hanya ada di open.mp, padahal juga ada di 0.3.7 (atau tidak bisa diverifikasi)`,
        });
      }
    });
  }

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else if (report.length === 0) {
    console.log('tidak ada klaim native yang bertentangan dengan matriks');
  } else {
    let current = '';
    for (const finding of report) {
      if (finding.skill !== current) {
        console.log(`\n${finding.skill}`);
        current = finding.skill;
      }
      console.log(`  ${finding.severity.toUpperCase()} L${finding.line} ${finding.name}: ${finding.message}`);
    }
  }

  const errors = report.filter((finding) => finding.severity === 'error').length;
  if (errors > 0) process.exitCode = 1;
}

main();
